void LaneChangeInterface::processOnExit()
{
  module_type_->resetParameters();
  debug_marker_.markers.clear();
  post_process_safety_status_ = {};
  interface_debug_ = {};
  resetPathCandidate();
}

void NormalLaneChange::resetParameters()
{
  is_abort_path_approved_ = false;
  is_abort_approval_requested_ = false;
  current_lane_change_state_ = LaneChangeStates::Normal;
  abort_path_ = nullptr;
  status_ = LaneChangeStatus();
  unsafe_hysteresis_count_ = 0;
  lane_change_debug_.reset();
  set_signal_activation_time(true);

  RCLCPP_DEBUG(logger_, "reset all flags and debug information.");
}

void set_signal_activation_time(const bool reset = false) const
{
  if (reset) {
    signal_activation_time_ = std::nullopt;
  } else if (!signal_activation_time_) {
    signal_activation_time_ = clock_.now();
  }
}
